import sys
from decimal import Decimal


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        a_str, op, b_str = line.split()
        a = Decimal(a_str)
        b = Decimal(b_str)
        if op == "+":
            result = a + b
        elif op == "-":
            result = a - b
        elif op == "*":
            result = a * b
        else:  # op == '/'
            if b == 0:
                print("ERROR")
                continue
            result = round(a / b, 10)
        # Formatting the output
        if result == 0:
            print("0")
        else:
            s = str(result)
            if "." in s:
                integer_part, fractional_part = s.split(".", 1)
            else:
                integer_part = s
                fractional_part = ""
            if fractional_part and fractional_part[-1] == "0":
                fractional_part = fractional_part[:-1]
            if integer_part and integer_part[0] == "0" and len(integer_part) > 1:
                integer_part = integer_part[1:]
            if not integer_part:
                print(f"0.{fractional_part}")
            else:
                print(f"{integer_part}.{fractional_part}")


if __name__ == "__main__":
    main()
